import os, re, glob, sys

BASE = sys.argv[1]
SGR = re.compile(rb"\x1b\[[0-9;]*[a-zA-Z]")
OSC = re.compile(rb"\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)")
OTH = re.compile(rb"\x1b[78]")


def visible(path):
    try:
        data = open(path, "rb").read()
    except OSError:
        return None
    for pattern in (OSC, SGR, OTH):
        data = pattern.sub(b"", data)
    return data.strip()


shorter = []
for path in sorted(glob.glob(os.path.join(BASE, "golden-a", "*.txt"))):
    name = os.path.basename(path)[:-4]
    hand = visible(path)
    rec = visible(os.path.join(BASE, "gold-a", name + ".txt"))
    if hand is None or rec is None:
        continue
    if len(rec) - len(hand) > 12:
        shorter.append((name, len(hand), len(rec)))

print("themes where the hand-written data file yields visibly LESS text:", len(shorter))
for name, h, r in shorter[:10]:
    print(f"  {name}: handwritten={h} recorded={r}")

